using System;using System.IO;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static partial class MiamiClothingBuild {
static void GunCapture(CityDayNightController ctrl,Tuple<Vector3,Quaternion> pose,string name){var go=new GameObject("Gangfire verification camera"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();go.transform.SetPositionAndRotation(pose.Item1,pose.Item2);cam.enabled=false;cam.fieldOfView=name.Contains("Detail")?50:60;if(name.Contains("Side-Left")){cam.orthographic=true;cam.orthographicSize=8.5f;}cam.farClipPlane=3500;cam.nearClipPlane=.2f;cam.allowHDR=true;cam.clearFlags=CameraClearFlags.Skybox;var data=cam.GetUniversalAdditionalCameraData();data.renderPostProcessing=true;data.volumeLayerMask=1;data.volumeTrigger=go.transform;data.antialiasing=AntialiasingMode.FastApproximateAntialiasing;var rt=RenderTexture.GetTemporary(1920,1080,24,RenderTextureFormat.ARGB32);var old=RenderTexture.active;try{cam.targetTexture=rt;ctrl.RefreshStreetLights(cam);for(int i=0;i<3;i++){VolumeManager.instance.Update(cam.transform,1);cam.Render();}RenderTexture.active=rt;var tex=new Texture2D(1920,1080,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1920,1080),0,0);tex.Apply();File.WriteAllBytes("DayNightReview/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{cam.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}
}


